public sealed class ProtectedPart
{
    public PKIHeader Header { get; set; }
    public PKIBody Body { get; set; }

    public void Encode(Asn1Writer writer) => Encode(writer, DefaultTag);

    public void Encode(Asn1Writer writer, Asn1Tag tag)
    {
        using (writer.EnterSequence(tag))
        {
            Header.Encode(writer, Asn1Tag.Sequence);
            Body.Encode(writer);
        }
    }

    public static ProtectedPart Decode(Asn1Reader reader) => Decode(reader, DefaultTag);

    public static ProtectedPart Decode(Asn1Reader reader, Asn1Tag tag)
    {
        using (reader.EnterSequence(tag))
        {
            var value = new ProtectedPart();
            value.Header = Asn1Kit.Modern.PKIXCMP2009.PKIHeader.Decode(reader, Asn1Tag.Sequence);
            value.Body = Asn1Kit.Modern.PKIXCMP2009.PKIBody.Decode(reader);
            reader.ThrowIfNotEmpty();
            return value;
        }
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.Sequence;
}

public sealed class PBMParameter
{
    public ReadOnlyMemory<byte> Salt { get; set; }
    public Asn1Kit.Modern.AlgorithmInformation2009.AlgorithmIdentifier Owf { get; set; }
    public Asn1Integer IterationCount { get; set; }
    public Asn1Kit.Modern.AlgorithmInformation2009.AlgorithmIdentifier Mac { get; set; }

    public void Encode(Asn1Writer writer) => Encode(writer, DefaultTag);

    public void Encode(Asn1Writer writer, Asn1Tag tag)
    {
        using (writer.EnterSequence(tag))
        {
            writer.WriteOctetString(Asn1Tag.OctetString, Salt.Span);
            Owf.Encode(writer, Asn1Tag.Sequence);
            writer.WriteInteger(Asn1Tag.Integer, IterationCount);
            Mac.Encode(writer, Asn1Tag.Sequence);
        }
    }

    public static PBMParameter Decode(Asn1Reader reader) => Decode(reader, DefaultTag);

    public static PBMParameter Decode(Asn1Reader reader, Asn1Tag tag)
    {
        using (reader.EnterSequence(tag))
        {
            var value = new PBMParameter();
            value.Salt = reader.ReadOctetString(Asn1Tag.OctetString);
            value.Owf = Asn1Kit.Modern.AlgorithmInformation2009.AlgorithmIdentifier.Decode(reader, Asn1Tag.Sequence);
            value.IterationCount = reader.ReadIntegerValue(Asn1Tag.Integer);
            value.Mac = Asn1Kit.Modern.AlgorithmInformation2009.AlgorithmIdentifier.Decode(reader, Asn1Tag.Sequence);
            reader.ThrowIfNotEmpty();
            return value;
        }
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.Sequence;
}

