    /// <summary>ASN.1 named bit unacceptedPolicy(15).</summary>
    UnacceptedPolicy = 1 << 15,
    /// <summary>ASN.1 named bit unacceptedExtension(16).</summary>
    UnacceptedExtension = 1 << 16,
    /// <summary>ASN.1 named bit addInfoNotAvailable(17).</summary>
    AddInfoNotAvailable = 1 << 17,
    /// <summary>ASN.1 named bit badSenderNonce(18).</summary>
    BadSenderNonce = 1 << 18,
    /// <summary>ASN.1 named bit badCertTemplate(19).</summary>
    BadCertTemplate = 1 << 19,
    /// <summary>ASN.1 named bit signerNotTrusted(20).</summary>
