    SystemUnavail = 1 << 24,
    /// <summary>ASN.1 named bit systemFailure(25).</summary>
    SystemFailure = 1 << 25,
    /// <summary>ASN.1 named bit duplicateCertReq(26).</summary>
    DuplicateCertReq = 1 << 26
}

public sealed class PKIFailureInfo
{
    public Asn1BitString Value { get; set; }

    public PKIFailureInfoFlags Flags
    {
        get => ToFlags(Value);
        set => Value = FromFlags(value);
    }

    public static PKIFailureInfoFlags ToFlags(Asn1BitString bits)
    {
        var flags = PKIFailureInfoFlags.None;
        if (bits.BitLength > 0 && bits[0]) flags |= PKIFailureInfoFlags.BadAlg;
        if (bits.BitLength > 1 && bits[1]) flags |= PKIFailureInfoFlags.BadMessageCheck;
        if (bits.BitLength > 2 && bits[2]) flags |= PKIFailureInfoFlags.BadRequest;
        if (bits.BitLength > 3 && bits[3]) flags |= PKIFailureInfoFlags.BadTime;
        if (bits.BitLength > 4 && bits[4]) flags |= PKIFailureInfoFlags.BadCertId;
        if (bits.BitLength > 5 && bits[5]) flags |= PKIFailureInfoFlags.BadDataFormat;
        if (bits.BitLength > 6 && bits[6]) flags |= PKIFailureInfoFlags.WrongAuthority;
        if (bits.BitLength > 7 && bits[7]) flags |= PKIFailureInfoFlags.IncorrectData;
        if (bits.BitLength > 8 && bits[8]) flags |= PKIFailureInfoFlags.MissingTimeStamp;
        if (bits.BitLength > 9 && bits[9]) flags |= PKIFailureInfoFlags.BadPOP;
        if (bits.BitLength > 10 && bits[10]) flags |= PKIFailureInfoFlags.CertRevoked;
        if (bits.BitLength > 11 && bits[11]) flags |= PKIFailureInfoFlags.CertConfirmed;
        if (bits.BitLength > 12 && bits[12]) flags |= PKIFailureInfoFlags.WrongIntegrity;
        if (bits.BitLength > 13 && bits[13]) flags |= PKIFailureInfoFlags.BadRecipientNonce;
        if (bits.BitLength > 14 && bits[14]) flags |= PKIFailureInfoFlags.TimeNotAvailable;
        if (bits.BitLength > 15 && bits[15]) flags |= PKIFailureInfoFlags.UnacceptedPolicy;
        if (bits.BitLength > 16 && bits[16]) flags |= PKIFailureInfoFlags.UnacceptedExtension;
        if (bits.BitLength > 17 && bits[17]) flags |= PKIFailureInfoFlags.AddInfoNotAvailable;
        if (bits.BitLength > 18 && bits[18]) flags |= PKIFailureInfoFlags.BadSenderNonce;
        if (bits.BitLength > 19 && bits[19]) flags |= PKIFailureInfoFlags.BadCertTemplate;
        if (bits.BitLength > 20 && bits[20]) flags |= PKIFailureInfoFlags.SignerNotTrusted;
        if (bits.BitLength > 21 && bits[21]) flags |= PKIFailureInfoFlags.TransactionIdInUse;
        if (bits.BitLength > 22 && bits[22]) flags |= PKIFailureInfoFlags.UnsupportedVersion;
        if (bits.BitLength > 23 && bits[23]) flags |= PKIFailureInfoFlags.NotAuthorized;
        if (bits.BitLength > 24 && bits[24]) flags |= PKIFailureInfoFlags.SystemUnavail;
        if (bits.BitLength > 25 && bits[25]) flags |= PKIFailureInfoFlags.SystemFailure;
        if (bits.BitLength > 26 && bits[26]) flags |= PKIFailureInfoFlags.DuplicateCertReq;
        return flags;
    }

    public static Asn1BitString FromFlags(PKIFailureInfoFlags flags)
    {
        var bits = new bool[27];
        if ((flags & PKIFailureInfoFlags.BadAlg) != 0) bits[0] = true;
        if ((flags & PKIFailureInfoFlags.BadMessageCheck) != 0) bits[1] = true;
        if ((flags & PKIFailureInfoFlags.BadRequest) != 0) bits[2] = true;
        if ((flags & PKIFailureInfoFlags.BadTime) != 0) bits[3] = true;
        if ((flags & PKIFailureInfoFlags.BadCertId) != 0) bits[4] = true;
        if ((flags & PKIFailureInfoFlags.BadDataFormat) != 0) bits[5] = true;
        if ((flags & PKIFailureInfoFlags.WrongAuthority) != 0) bits[6] = true;
        if ((flags & PKIFailureInfoFlags.IncorrectData) != 0) bits[7] = true;
        if ((flags & PKIFailureInfoFlags.MissingTimeStamp) != 0) bits[8] = true;
        if ((flags & PKIFailureInfoFlags.BadPOP) != 0) bits[9] = true;
        if ((flags & PKIFailureInfoFlags.CertRevoked) != 0) bits[10] = true;
        if ((flags & PKIFailureInfoFlags.CertConfirmed) != 0) bits[11] = true;
        if ((flags & PKIFailureInfoFlags.WrongIntegrity) != 0) bits[12] = true;
        if ((flags & PKIFailureInfoFlags.BadRecipientNonce) != 0) bits[13] = true;
        if ((flags & PKIFailureInfoFlags.TimeNotAvailable) != 0) bits[14] = true;
        if ((flags & PKIFailureInfoFlags.UnacceptedPolicy) != 0) bits[15] = true;
        if ((flags & PKIFailureInfoFlags.UnacceptedExtension) != 0) bits[16] = true;
        if ((flags & PKIFailureInfoFlags.AddInfoNotAvailable) != 0) bits[17] = true;
        if ((flags & PKIFailureInfoFlags.BadSenderNonce) != 0) bits[18] = true;
        if ((flags & PKIFailureInfoFlags.BadCertTemplate) != 0) bits[19] = true;
        if ((flags & PKIFailureInfoFlags.SignerNotTrusted) != 0) bits[20] = true;
        if ((flags & PKIFailureInfoFlags.TransactionIdInUse) != 0) bits[21] = true;
        if ((flags & PKIFailureInfoFlags.UnsupportedVersion) != 0) bits[22] = true;
        if ((flags & PKIFailureInfoFlags.NotAuthorized) != 0) bits[23] = true;
        if ((flags & PKIFailureInfoFlags.SystemUnavail) != 0) bits[24] = true;
        if ((flags & PKIFailureInfoFlags.SystemFailure) != 0) bits[25] = true;
        if ((flags & PKIFailureInfoFlags.DuplicateCertReq) != 0) bits[26] = true;
        var length = bits.Length;
        while (length > 0 && !bits[length - 1])
        {
            length--;
        }
        return Asn1BitString.FromBits(bits.AsSpan(0, length));
    }

    public void Encode(Asn1Writer writer) => Encode(writer, DefaultTag);

    public void Encode(Asn1Writer writer, Asn1Tag tag)
    {
        writer.WriteBitString(tag, Value);
    }

    public static PKIFailureInfo Decode(Asn1Reader reader) => Decode(reader, DefaultTag);

    public static PKIFailureInfo Decode(Asn1Reader reader, Asn1Tag tag)
    {
        return new PKIFailureInfo { Value = reader.ReadBitString(tag) };
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.BitString;
}

public sealed class PKIStatusInfo
{
    public int Status { get; set; }
    /// <summary>ASN.1 alias PKIFreeText ::= SEQUENCE OF UTF8String.</summary>
    public string[]? StatusString { get; set; }
    public PKIFailureInfo? FailInfo { get; set; }

    public void Encode(Asn1Writer writer) => Encode(writer, DefaultTag);

    public void Encode(Asn1Writer writer, Asn1Tag tag)
    {
        using (writer.EnterSequence(tag))
        {
            writer.WriteInteger(Asn1Tag.Integer, Status);
            if (StatusString != null)
            {
                writer.WriteSequenceOf(Asn1Tag.Sequence, StatusString, static (inner, item) =>
                {
                    inner.WriteString(Asn1Tag.Utf8String, item, Asn1StringForm.Utf8);
                });
            }
            if (FailInfo != null)
            {
                FailInfo.Encode(writer, Asn1Tag.BitString);
            }
        }
    }

    public static PKIStatusInfo Decode(Asn1Reader reader) => Decode(reader, DefaultTag);

    public static PKIStatusInfo Decode(Asn1Reader reader, Asn1Tag tag)
    {
        using (reader.EnterSequence(tag))
        {
            var value = new PKIStatusInfo();
            value.Status = reader.ReadInt32(Asn1Tag.Integer);
            if (reader.TryPeekTag(out var tag_StatusString) && tag_StatusString.MatchesIgnoreConstructed(Asn1Tag.Sequence))
            {
                value.StatusString = reader.ReadSequenceOf(Asn1Tag.Sequence, static inner => inner.ReadString(Asn1Tag.Utf8String, Asn1StringForm.Utf8));
            }
            if (reader.TryPeekTag(out var tag_FailInfo) && tag_FailInfo.MatchesIgnoreConstructed(Asn1Tag.BitString))
            {
                value.FailInfo = Asn1Kit.Modern.PKIXCMP2009.PKIFailureInfo.Decode(reader, Asn1Tag.BitString);
            }
            reader.ThrowIfNotEmpty();
            return value;
        }
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.Sequence;
}

