public enum CertOrEncCertKind
{
    Certificate,
    EncryptedCert,
}

public sealed class CertOrEncCert
{
    public CertOrEncCertKind Kind { get; private set; }
    public CMPCertificate? Certificate { get; private set; }
    public Asn1Kit.Modern.PKIXCRMF2009.EncryptedValue? EncryptedCert { get; private set; }

    public static CertOrEncCert FromCertificate(CMPCertificate certificate) => new CertOrEncCert
    {
        Kind = CertOrEncCertKind.Certificate,
        Certificate = certificate,
    };

    public static CertOrEncCert FromEncryptedCert(Asn1Kit.Modern.PKIXCRMF2009.EncryptedValue encryptedCert) => new CertOrEncCert
    {
        Kind = CertOrEncCertKind.EncryptedCert,
        EncryptedCert = encryptedCert,
    };

    public override string ToString()
    {
        return Kind switch
        {
            CertOrEncCertKind.Certificate => Asn1Formatting.Format(Certificate),
            CertOrEncCertKind.EncryptedCert => Asn1Formatting.Format(EncryptedCert),
            _ => "<unset>",
        };
    }

    public void Encode(Asn1Writer writer)
    {
        switch (Kind)
        {
            case CertOrEncCertKind.Certificate:
                using (writer.EnterExplicit(new Asn1Tag(Asn1TagClass.ContextSpecific, 0, true)))
                {
                    Certificate.Encode(writer);
                }
                break;
            case CertOrEncCertKind.EncryptedCert:
                using (writer.EnterExplicit(new Asn1Tag(Asn1TagClass.ContextSpecific, 1, true)))
                {
                    EncryptedCert.Encode(writer, Asn1Tag.Sequence);
                }
                break;
            default: throw new Asn1Exception("CHOICE has no alternative.");
        }
    }

    public static CertOrEncCert Decode(Asn1Reader reader)
    {
        if (!reader.TryPeekTag(out var peeked)) throw new Asn1Exception("Empty CHOICE.");
        var value = new CertOrEncCert();
        if (peeked.MatchesIgnoreConstructed(new Asn1Tag(Asn1TagClass.ContextSpecific, 0, true)))
        {
            value.Kind = CertOrEncCertKind.Certificate;
            using (reader.EnterExplicit(new Asn1Tag(Asn1TagClass.ContextSpecific, 0, true)))
            {
                value.Certificate = Asn1Kit.Modern.PKIXCMP2009.CMPCertificate.Decode(reader);
                reader.ThrowIfNotEmpty();
            }
        }
        else if (peeked.MatchesIgnoreConstructed(new Asn1Tag(Asn1TagClass.ContextSpecific, 1, true)))
        {
            value.Kind = CertOrEncCertKind.EncryptedCert;
            using (reader.EnterExplicit(new Asn1Tag(Asn1TagClass.ContextSpecific, 1, true)))
            {
                value.EncryptedCert = Asn1Kit.Modern.PKIXCRMF2009.EncryptedValue.Decode(reader, Asn1Tag.Sequence);
                reader.ThrowIfNotEmpty();
            }
        }
        else throw new Asn1Exception("Unknown CHOICE alternative.");
        return value;
    }
}

